define('BrandMark','앱 아이콘','기본 요소','Q·검증 체크·반복 검증의 원형을 결합한 QAutra 앱 아이콘이에요.',['size','label'],function(p){const size=['sm','md','lg','hero'].includes(p.size)?p.size:'md';return '<img class="qa-brand-art qa-brand-art-'+size+'" src="'+esc(global.QAUTRA_ICON_DATA||'assets/icons/qautra-app-icon.svg')+'" width="1024" height="1024" alt="'+esc(p.label==null?'QAutra 앱 아이콘':p.label)+'">'},['sm 32px · md 40px · lg 128px · hero 256px 중에서 선택해요.','원본의 정사각 비율과 투명 여백을 유지하고 별도 배경이나 모서리를 덧씌우지 않아요.','같은 원본을 앱·문서·Dock에서 사용하고 흰 심벌의 형태와 브랜드 파란색을 변경하지 않아요.']);
